function active$VoucherFilter$(f) {
  f.add_onResponseComplete(on$Filter$ResponseComplete);
  changeLookupReadonly(f, 'ma_dvcs');
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
  var f = e.object, context = e.type.Context, result = e.type.Result;
  switch (context) {
    case 'Checking':
      var g = f.grid, x = f.getItem('form').selectedIndex, y = f.getItem('form').options, formName = y[x].text, v = f.getItemValue('mau_bc');
      var d1 = f.getItem('tu_ngay').value, d2 = f.getItem('den_ngay').value;
      g._alterTitle = [null, [['%f', formName, true], ['%d1', d1, true], ['%d2', d2, true]]];
      // AGENT: sửa _hiddenFields theo cặp cột tiền tệ thật của grid.xml
      g._hiddenFields = [
        {Fields: 'name_decimal_3, name_decimal_4', Value: v == '10'},
        {Fields: 'name_decimal_1, name_decimal_2', Value: v == '20'}
      ];
      g._nam = (function (v) {
        if (!v) return (new Date()).getFullYear();
        var s = String(v);
        if (/^\d{8}/.test(s)) return parseInt(s.substring(0, 4), 10);
        try { if (v.getFullYear) return v.getFullYear(); } catch (ex) {}
        return (new Date()).getFullYear();
      })(d2);
      break;
    default:
      break;
  }
}
function init$&controller;$Form(f) {
  var o = f.getItem('form'), value = f._itemValue.split(String.fromCharCode(255)), text = f._itemText.split(String.fromCharCode(255)), index;
  for (var i = 0; i < value.length; i++) {
    o.options[i] = new Option(text[i], value[i]);
    if (!index && f._defaultForm == value[i]) index = i;
  }
  if (!index) index = 0;
  o.options[index].selected = true;
}




